function Topbar({ setActive, onMenu, collapsed, setCollapsed }: { setActive: (id: string) => void, onMenu: () => void, collapsed: boolean, setCollapsed: () => void }) { return <header className="flex h-20 items-center gap-4 border-b bg-card/80 px-4 backdrop-blur sm:px-8"><Button variant="ghost" size="icon" className="lg:hidden" onClick={onMenu} aria-label="Abrir menú"><Menu /></Button><Button variant="ghost" size="icon" className="hidden lg:inline-flex" onClick={setCollapsed} aria-label={collapsed ? 'Expandir barra lateral' : 'Contraer barra lateral'}>{collapsed ? <PanelLeftOpen /> : <PanelLeftClose />}</Button><div className="relative hidden max-w-md flex-1 md:block"><Search className="absolute left-3 top-2.5 size-4 text-muted-foreground" /><Input placeholder="Buscar en DotaControl..." className="h-9 border-0 bg-muted/60 pl-9 text-xs shadow-none" /></div><div className="ml-auto flex items-center gap-1"><Popover><PopoverTrigger><Button variant="ghost" size="icon" className="relative" aria-label="Notificaciones"><Bell /><span className="absolute right-2 top-1.5 size-1.5 rounded-full bg-primary" /></Button></PopoverTrigger><PopoverContent align="end" className="w-80"><p className="font-semibold">Notificaciones</p><div className="mt-3 flex flex-col gap-3 text-xs"><p><span className="font-medium">Stock bajo:</span> botas de seguridad requieren reposición.</p><p><span className="font-medium">Nueva entrega:</span> Carlos Rodríguez tiene una entrega pendiente.</p></div></PopoverContent></Popover><Button variant="ghost" size="icon" aria-label="Cambiar tema"><Sun /><Moon className="hidden" /></Button><Separator orientation="vertical" className="mx-2 h-6" /><DropdownMenu><DropdownMenuTrigger className="inline-flex h-9 items-center gap-2 rounded-md px-1.5 text-sm hover:bg-muted"><Avatar className="size-8"><AvatarFallback className="bg-primary/10 text-xs font-semibold text-primary">AM</AvatarFallback></Avatar><span className="hidden text-left text-xs sm:block"><span className="block font-semibold">Ana Martínez</span><span className="block text-muted-foreground">Administradora</span></span><ChevronDown className="size-3.5 text-muted-foreground" /></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem><UserRound /> Mi perfil</DropdownMenuItem><DropdownMenuItem onClick={() => setActive('settings')}><Settings /> Configuración</DropdownMenuItem><DropdownMenuItem onClick={() => setActive('login')}><LogIn /> Cerrar sesión</DropdownMenuItem></DropdownMenuContent></DropdownMenu></div></header> }

function Dashboard({ setActive }: { setActive: (id: string) => void }) { return <div className="flex flex-col gap-8"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-sm text-muted-foreground">Viernes, 20 de septiembre de 2026</p><h1 className="mt-1 text-2xl font-bold tracking-tight">Buenos días, Ana</h1><p className="mt-1 text-sm text-muted-foreground">Este es el estado de tu operación hoy.</p></div><Button onClick={() => setActive('delivery')}><Plus data-icon="inline-start" /> Nueva entrega</Button></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[['Elementos en inventario','1.284','+12% vs. mes anterior',Package],['Entregas este mes','64','+8% vs. mes anterior',Truck],['Empleados activos','186','+4 nuevos este mes',Users],['Por reponer','12','Requieren atención',AlertTriangle]].map(([title,value,detail,Icon], i) => <Card key={title as string} className={i === 3 ? 'border-amber-200 bg-amber-50/50 dark:border-amber-900 dark:bg-amber-950/20' : ''}><CardContent className="flex items-start justify-between p-5"><div><p className="text-xs font-medium text-muted-foreground">{title as string}</p><p className="mt-2 text-2xl font-bold">{value as string}</p><p className="mt-1 text-[11px] text-muted-foreground">{detail as string}</p></div><div className="rounded-lg bg-muted p-2.5"><Icon className="size-4 text-muted-foreground" /></div></CardContent></Card>)}</div><div className="grid gap-5 xl:grid-cols-[1.4fr_1fr]"><Card><CardHeader className="flex flex-row items-center justify-between"><div><CardTitle className="text-base">Movimientos recientes</CardTitle><CardDescription>Últimas entregas registradas</CardDescription></div><Button variant="ghost" size="sm" onClick={() => setActive('record')}>Ver todo <ArrowRight data-icon="inline-end" /></Button></CardHeader><CardContent><Table><TableHeader><TableRow><TableHead>Empleado</TableHead><TableHead>Área</TableHead><TableHead>Fecha</TableHead><TableHead>Estado</TableHead></TableRow></TableHeader><TableBody>{[['Carlos Rodríguez','Operaciones','Hoy, 09:42','Firmada'],['Luisa Fernanda Díaz','Mantenimiento','Ayer, 16:20','Pendiente firma'],['Miguel Torres','Bodega','18 sep, 11:05','Firmada'],['Sofía Vargas','Logística','17 sep, 14:36','Firmada']].map(([name,area,date,status]) => <TableRow key={name}><TableCell><div className="flex items-center gap-2.5"><Avatar className="size-7"><AvatarFallback className="bg-muted text-[10px]">{(name as string).split(' ').map(n=>n[0]).slice(0,2).join('')}</AvatarFallback></Avatar><span className="text-sm font-medium">{name}</span></div></TableCell><TableCell className="text-xs text-muted-foreground">{area}</TableCell><TableCell className="text-xs text-muted-foreground">{date}</TableCell><TableCell><Badge variant={status === 'Firmada' ? 'secondary' : 'outline'} className="text-[10px]">{status}</Badge></TableCell></TableRow>)}</TableBody></Table></CardContent></Card><Card><CardHeader><CardTitle className="text-base">Alertas de inventario</CardTitle><CardDescription>Elementos que necesitan atención</CardDescription></CardHeader><CardContent className="flex flex-col gap-3">{items.slice(1,3).map(item => <div key={item.sku} className="flex items-center justify-between rounded-lg border p-3"><div className="flex items-center gap-3"><div className="rounded-md bg-muted p-2"><Shirt className="size-4 text-muted-foreground" /></div><div><p className="text-xs font-semibold">{item.name}</p><p className="mt-0.5 text-[11px] text-muted-foreground">{item.sku} · Mínimo {item.min} uds.</p></div></div><Badge variant={item.stock ? 'outline' : 'destructive'} className="text-[10px]">{item.stock ? `${item.stock} uds.` : 'Agotado'}</Badge></div>)}<Button variant="outline" size="sm" className="mt-1" onClick={() => setActive('inventory')}>Gestionar inventario <ArrowRight data-icon="inline-end" /></Button></CardContent></Card></div></div> }

function Inventory({ setActive }: { setActive: (id: string) => void }) { return <div className="flex flex-col gap-6"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-sm text-muted-foreground">Inventario / Elementos</p><h1 className="mt-1 text-2xl font-bold tracking-tight">Elementos de dotación</h1><p className="mt-1 text-sm text-muted-foreground">Administra el catálogo y existencias de tu organización.</p></div><Button onClick={() => setActive('new-item')}><Plus data-icon="inline-start" /> Registrar elemento</Button></div><div className="grid gap-4 sm:grid-cols-3"><Card><CardContent className="p-4"><p className="text-xs text-muted-foreground">Total elementos</p><p className="mt-1 text-xl font-bold">86</p></CardContent></Card><Card><CardContent className="p-4"><p className="text-xs text-muted-foreground">En stock</p><p className="mt-1 text-xl font-bold">72</p></CardContent></Card><Card className="border-amber-200 bg-amber-50/50"><CardContent className="p-4"><p className="text-xs text-muted-foreground">Stock bajo / agotado</p><p className="mt-1 text-xl font-bold text-amber-700">14</p></CardContent></Card></div><Card><CardHeader className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><CardTitle className="text-base">Catálogo de elementos</CardTitle><CardDescription>Última actualización: hoy, 08:30</CardDescription></div><div className="flex gap-2"><div className="relative"><Search className="absolute left-3 top-2.5 size-4 text-muted-foreground" /><Input placeholder="Buscar elemento..." className="h-9 w-48 pl-9 text-xs" /></div><Button variant="outline" size="icon"><SlidersHorizontal /></Button></div></CardHeader><CardContent><Table><TableHeader><TableRow><TableHead>Elemento</TableHead><TableHead>Categoría</TableHead><TableHead>Existencias</TableHead><TableHead>Estado</TableHead><TableHead className="text-right">Acciones</TableHead></TableRow></TableHeader><TableBody>{items.map(item => <TableRow key={item.sku}><TableCell><div><p className="text-sm font-medium">{item.name}</p><p className="text-[11px] text-muted-foreground">{item.sku}</p></div></TableCell><TableCell><Badge variant="outline" className="font-normal">{item.category}</Badge></TableCell><TableCell className="text-sm">{item.stock} uds.</TableCell><TableCell><Badge variant={item.status === 'En stock' ? 'secondary' : item.status === 'Stock bajo' ? 'outline' : 'destructive'}>{item.status}</Badge></TableCell><TableCell className="text-right"><DropdownMenu><DropdownMenuTrigger><Button variant="ghost" size="icon"><MoreHorizontal /></Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem><Eye /> Ver detalle</DropdownMenuItem><DropdownMenuItem><SlidersHorizontal /> Editar</DropdownMenuItem></DropdownMenuContent></DropdownMenu></TableCell></TableRow>)}</TableBody></Table></CardContent></Card></div> }

function Field({ label, placeholder, type = 'text' }: { label: string, placeholder?: string, type?: string }) { return <div className="flex flex-col gap-2"><Label className="text-xs font-medium">{label}</Label><Input type={type} placeholder={placeholder} /></div> }

const deliveryEmployees = [
  { id: '1.023.456.789', name: 'Carlos Rodríguez', position: 'Operario de bodega', area: 'Logística', initials: 'CR' },
  { id: '1.015.884.220', name: 'Laura Méndez', position: 'Supervisora de operaciones', area: 'Operaciones', initials: 'LM' },
  { id: '1.098.334.761', name: 'Julián Torres', position: 'Técnico de mantenimiento', area: 'Mantenimiento', initials: 'JT' },
]
const deliveryItems = [
  { id: 'shirt', name: 'Camisa manga larga azul', sku: 'UNI-001', stock: 48, sizes: ['S', 'M', 'L', 'XL'] },
  { id: 'boots', name: 'Botas de seguridad punta acero', sku: 'CAL-014', stock: 6, sizes: ['37', '38', '39', '40', '41', '42'] },
  { id: 'gloves', name: 'Guantes anticorte nivel 5', sku: 'PPE-021', stock: 32, sizes: ['Única'] },
  { id: 'vest', name: 'Chaleco reflectivo', sku: 'UNI-032', stock: 25, sizes: ['S', 'M', 'L', 'XL'] },
]
const deliverySchema = z.object({
  employee: z.string().min(1, 'Selecciona un empleado para continuar.'),
  items: z.array(z.object({ itemId: z.string(), name: z.string(), size: z.string().min(1), quantity: z.number().int().min(1), stock: z.number() })).min(1, 'Agrega al menos un elemento.'),
  date: z.date({ error: 'Selecciona la fecha de entrega.' }),
  reason: z.string().min(1, 'Selecciona un motivo.'),
  deliveredBy: z.string().min(2, 'Indica quién realiza la entrega.'),
  observations: z.string().optional(),
})
type DeliveryValues = z.infer<typeof deliverySchema>

type DeliveryLine = { itemId: string; name: string; size: string; quantity: number; stock: number }

function Delivery({ setActive }: { setActive: (id: string) => void }) {
  const [step, setStep] = useState('employee')
  const [employeeSearchOpen, setEmployeeSearchOpen] = useState(false)
  const [itemDialogOpen, setItemDialogOpen] = useState(false)
  const [itemSearch, setItemSearch] = useState('')
  const [lines, setLines] = useState<DeliveryLine[]>([])
  const form = useForm<DeliveryValues>({ resolver: zodResolver(deliverySchema), defaultValues: { employee: '', items: [], date: new Date(), reason: '', deliveredBy: 'Ana Martínez', observations: '' }, mode: 'onTouched' })
  const employeeId = form.watch('employee')
  const employee = deliveryEmployees.find((person) => person.id === employeeId)
  const totalUnits = lines.reduce((sum, line) => sum + line.quantity, 0)
  const selectEmployee = (person: typeof deliveryEmployees[number]) => { form.setValue('employee', person.id, { shouldValidate: true }); setEmployeeSearchOpen(false) }
  const addItem = (item: typeof deliveryItems[number]) => { if (lines.some((line) => line.itemId === item.id)) return; const next = [...lines, { itemId: item.id, name: item.name, size: item.sizes[0], quantity: 1, stock: item.stock }]; setLines(next); form.setValue('items', next, { shouldValidate: true }); setItemDialogOpen(false) }
  const updateLine = (itemId: string, patch: Partial<DeliveryLine>) => { const next = lines.map((line) => line.itemId === itemId ? { ...line, ...patch } : line); setLines(next); form.setValue('items', next, { shouldValidate: true }) }
  const removeLine = (itemId: string) => { const next = lines.filter((line) => line.itemId !== itemId); setLines(next); form.setValue('items', next, { shouldValidate: true }) }
  const nextStep = async () => { const fields = step === 'employee' ? ['employee'] : step === 'items' ? ['items'] : ['date', 'reason', 'deliveredBy']; const valid = await form.trigger(fields as (keyof DeliveryValues)[]); if (!valid) return; setStep(step === 'employee' ? 'items' : 'details') }
  const saveDraft = () => toast.success('Borrador guardado', { description: 'La entrega quedó guardada para continuar después.' })
  const confirm = async () => { if (!await form.trigger()) return; toast.success('Entrega confirmada', { description: 'La asignación se registró correctamente.', action: { label: 'Generar registro', onClick: () => setActive('record') } }) }
  return <div className="flex flex-col gap-6">
    <div><Breadcrumb className="mb-4"><BreadcrumbList><BreadcrumbItem><BreadcrumbLink>Entregas</BreadcrumbLink></BreadcrumbItem><BreadcrumbSeparator /><BreadcrumbItem><BreadcrumbPage>Nueva entrega</BreadcrumbPage></BreadcrumbItem></BreadcrumbList></Breadcrumb><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h1 className="text-2xl font-bold tracking-tight">Registrar entrega</h1><p className="mt-1 text-sm text-muted-foreground">Asigna elementos de dotación a un empleado.</p></div><Button variant="outline" onClick={saveDraft}>Guardar como borrador</Button></div></div>
    <Tabs value={step} onValueChange={setStep} className="w-full"><TabsList className="grid h-auto w-full grid-cols-3 bg-muted/70 p-1 sm:max-w-xl"><TabsTrigger value="employee" className="gap-2 py-2.5"><span className="flex size-5 items-center justify-center rounded-full bg-background text-[11px]">1</span><span className="hidden sm:inline">Empleado</span></TabsTrigger><TabsTrigger value="items" className="gap-2 py-2.5"><span className="flex size-5 items-center justify-center rounded-full bg-background text-[11px]">2</span><span className="hidden sm:inline">Elementos</span></TabsTrigger><TabsTrigger value="details" className="gap-2 py-2.5"><span className="flex size-5 items-center justify-center rounded-full bg-background text-[11px]">3</span><span className="hidden sm:inline">Detalles</span></TabsTrigger></TabsList>
      <div className="grid items-start gap-5 pt-5 xl:grid-cols-[minmax(0,1fr)_320px]"><div>
        <TabsContent value="employee" className="mt-0"><Card><CardHeader><CardTitle className="text-base">Selecciona un empleado</CardTitle><CardDescription>Busca por nombre o número de identificación.</CardDescription></CardHeader><CardContent className="flex flex-col gap-4"><Popover open={employeeSearchOpen} onOpenChange={setEmployeeSearchOpen}><PopoverTrigger><Button variant="outline" role="combobox" className="justify-start gap-3 font-normal"><Search className="size-4 text-muted-foreground" />{employee ? employee.name : 'Buscar empleado por nombre o cédula'}</Button></PopoverTrigger><PopoverContent className="w-[min(420px,calc(100vw-3rem))] p-0" align="start"><Command><CommandInput placeholder="Buscar empleado..." /><CommandList><CommandEmpty>No se encontraron empleados.</CommandEmpty><CommandGroup heading="Empleados"><CommandItem value={`${deliveryEmployees[0].name} ${deliveryEmployees[0].id}`} onSelect={() => selectEmployee(deliveryEmployees[0])}>{deliveryEmployees[0].name}<span className="ml-auto text-xs text-muted-foreground">{deliveryEmployees[0].id}</span></CommandItem><CommandItem value={`${deliveryEmployees[1].name} ${deliveryEmployees[1].id}`} onSelect={() => selectEmployee(deliveryEmployees[1])}>{deliveryEmployees[1].name}<span className="ml-auto text-xs text-muted-foreground">{deliveryEmployees[1].id}</span></CommandItem><CommandItem value={`${deliveryEmployees[2].name} ${deliveryEmployees[2].id}`} onSelect={() => selectEmployee(deliveryEmployees[2])}>{deliveryEmployees[2].name}<span className="ml-auto text-xs text-muted-foreground">{deliveryEmployees[2].id}</span></CommandItem></CommandGroup></CommandList></Command></PopoverContent></Popover>{form.formState.errors.employee && <p className="text-xs text-destructive">{form.formState.errors.employee.message}</p>}{employee && <Card className="border-primary/20 bg-primary/[0.03] shadow-none"><CardContent className="flex items-center gap-4 p-4"><Avatar className="size-12"><AvatarFallback className="bg-primary/10 text-primary">{employee.initials}</AvatarFallback></Avatar><div className="min-w-0 flex-1"><p className="font-semibold">{employee.name}</p><p className="text-xs text-muted-foreground">{employee.position} · {employee.area}</p><p className="mt-1 text-[11px] text-muted-foreground">CC {employee.id}</p></div><Check className="size-5 text-primary" /></CardContent></Card>}<div className="flex justify-end pt-2"><Button onClick={nextStep}>Continuar <ArrowRight data-icon="inline-end" /></Button></div></CardContent></Card></TabsContent>
        
 {/* @ts-expect-error Base UI accepts nullable trigger values at runtime. */}
 <TabsContent value="items" className="mt-0"><Card><CardHeader className="flex flex-row items-center justify-between gap-4"><div><CardTitle className="text-base">Elementos a entregar</CardTitle><CardDescription>Define las tallas y cantidades de cada elemento.</CardDescription></div><Dialog open={itemDialogOpen} onOpenChange={setItemDialogOpen}><DialogTrigger><Button size="sm"><Plus data-icon="inline-start" /> Agregar elemento</Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>Agregar elemento</DialogTitle></DialogHeader><Command><CommandInput value={itemSearch} onValueChange={setItemSearch} placeholder="Buscar en inventario..." /><CommandList><CommandEmpty>No hay elementos disponibles.</CommandEmpty><CommandGroup heading="Inventario">{deliveryItems.filter((item) => `${item.name} ${item.sku}`.toLowerCase().includes(itemSearch.toLowerCase())).map((item) => <CommandItem key={item.id} value={item.name} disabled={lines.some((line) => line.itemId === item.id)} onSelect={() => addItem(item)}><div><p>{item.name}</p><p className="text-xs text-muted-foreground">{item.sku} · {item.stock} disponibles</p></div></CommandItem>)}</CommandGroup></CommandList></Command></DialogContent></Dialog></CardHeader><CardContent>{lines.length === 0 ? <div className="flex flex-col items-center gap-2 rounded-lg border border-dashed py-12 text-center"><Package className="size-8 text-muted-foreground/60" /><p className="text-sm font-medium">Aún no hay elementos</p><p className="text-xs text-muted-foreground">Agrega elementos desde el inventario para continuar.</p></div> : <div className="overflow-x-auto"><Table><TableHeader><TableRow><TableHead>Elemento</TableHead><TableHead>Talla</TableHead><TableHead>Cantidad</TableHead><TableHead>Disponibles</TableHead><TableHead className="w-10" /></TableRow></TableHeader><TableBody>{lines.map((line) => <TableRow key={line.itemId}><TableCell className="min-w-48 font-medium">{line.name}</TableCell><TableCell><Select value={line.size} onValueChange={(size) => updateLine(line.itemId, { size })}><SelectTrigger className="w-24"><SelectValue /></SelectTrigger><SelectContent>{deliveryItems.find((item) => item.id === line.itemId)?.sizes.map((size) => <SelectItem key={size} value={size}>{size}</SelectItem>)}</SelectContent></Select></TableCell><TableCell><Input type="number" min={1} value={line.quantity} onChange={(event) => updateLine(line.itemId, { quantity: Number(event.target.value) })} className="w-20" /></TableCell><TableCell><Badge variant={line.quantity > line.stock ? 'destructive' : 'secondary'}>{line.stock} unidades</Badge></TableCell><TableCell><Button variant="ghost" size="icon" aria-label={`Quitar ${line.name}`} onClick={() => removeLine(line.itemId)}><X /></Button></TableCell></TableRow>)}</TableBody></Table>{lines.some((line) => line.quantity > line.stock) && <Alert variant="destructive" className="mt-4"><AlertTriangle className="size-4" /><AlertTitle>Stock insuficiente</AlertTitle><AlertDescription>Una o más cantidades superan las existencias disponibles.</AlertDescription></Alert>}{form.formState.errors.items && <p className="mt-3 text-xs text-destructive">{form.formState.errors.items.message}</p>}</div>}<div className="flex justify-between pt-5"><Button variant="outline" onClick={() => setStep('employee')}><ChevronLeft data-icon="inline-start" /> Atrás</Button><Button onClick={nextStep}>Continuar <ArrowRight data-icon="inline-end" /></Button></div></CardContent></Card></TabsContent>
        <TabsContent value="details" className="mt-0"><Card><CardHeader><CardTitle className="text-base">Detalles de la entrega</CardTitle><CardDescription>Completa la información para generar el registro.</CardDescription></CardHeader><CardContent><Form {...form}><div className="grid gap-5 sm:grid-cols-2"><FormField control={form.control} name="date" render={({ field }) => <FormItem><FormLabel>Fecha de entrega</FormLabel><Popover><PopoverTrigger><FormControl><Button variant="outline" className="w-full justify-start font-normal"><CalendarDays className="mr-2 size-4" />{field.value?.toLocaleDateString('es-CO') ?? 'Selecciona una fecha'}</Button></FormControl></PopoverTrigger><PopoverContent className="w-auto p-0"><Calendar mode="single" selected={field.value} onSelect={field.onChange} /></PopoverContent></Popover><FormMessage /></FormItem>} /><FormField control={form.control} name="reason" render={({ field }) => <FormItem><FormLabel>Motivo de entrega</FormLabel><Select value={field.value ?? ''} onValueChange={field.onChange}><FormControl><SelectTrigger><SelectValue placeholder="Selecciona un motivo" /></SelectTrigger></FormControl><SelectContent><SelectItem value="new">Nuevo ingreso</SelectItem><SelectItem value="replacement">Reposición</SelectItem><SelectItem value="annual">Renovación anual</SelectItem><SelectItem value="damage">Daño o pérdida</SelectItem></SelectContent></Select><FormMessage /></FormItem>} /><FormField control={form.control} name="deliveredBy" render={({ field }) => <FormItem><FormLabel>Entregado por</FormLabel><FormControl><Input placeholder="Nombre de quien entrega" {...field} /></FormControl><FormMessage /></FormItem>} /><FormField control={form.control} name="observations" render={({ field }) => <FormItem className="sm:col-span-2"><FormLabel>Observaciones</FormLabel><FormControl><Textarea placeholder="Añade información adicional (opcional)" {...field} /></FormControl><FormMessage /></FormItem>} /></div></Form><div className="mt-6 flex flex-wrap justify-between gap-3"><Button variant="outline" onClick={() => setStep('items')}><ChevronLeft data-icon="inline-start" /> Atrás</Button><div className="flex gap-2"><Button variant="outline" onClick={saveDraft}>Guardar como borrador</Button><Button onClick={confirm}><ClipboardCheck data-icon="inline-start" /> Confirmar entrega</Button></div></div></CardContent></Card></TabsContent>
      </div><Card className="sticky top-5"><CardHeader><CardTitle className="text-base">Resumen de entrega</CardTitle><CardDescription>Se actualiza automáticamente</CardDescription></CardHeader><CardContent className="flex flex-col gap-4 text-sm">{employee ? <div className="flex items-center gap-3"><Avatar className="size-9"><AvatarFallback className="bg-primary/10 text-xs text-primary">{employee.initials}</AvatarFallback></Avatar><div className="min-w-0"><p className="truncate font-medium">{employee.name}</p><p className="text-xs text-muted-foreground">{employee.area}</p></div></div> : <p className="text-xs text-muted-foreground">Selecciona un empleado para comenzar.</p>}<Separator /><div className="flex flex-col gap-3">{lines.length ? lines.map((line) => <div key={line.itemId} className="flex justify-between gap-3 text-xs"><span className="truncate">{line.name}<span className="ml-1 text-muted-foreground">({line.size})</span></span><span className="shrink-0 font-medium">{line.quantity}</span></div>) : <p className="text-xs text-muted-foreground">Sin elementos agregados</p>}</div><Separator /><div className="grid grid-cols-2 gap-3"><div className="rounded-lg bg-muted/60 p-3"><p className="text-xs text-muted-foreground">Elementos</p><p className="mt-1 text-lg font-semibold">{lines.length}</p></div><div className="rounded-lg bg-muted/60 p-3"><p className="text-xs text-muted-foreground">Unidades</p><p className="mt-1 text-lg font-semibold">{totalUnits}</p></div></div></CardContent></Card></div>
    </Tabs>
  </div>
}

function DeliveryRecordDetail() {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const [emailOpen, setEmailOpen] = useState(false)
  useEffect(() => { const canvas = canvasRef.current; if (!canvas) return; const context = canvas.getContext('2d'); if (!context) return; context.strokeStyle = '#0f766e'; context.lineWidth = 2; context.lineCap = 'round'; let drawing = false; const point = (event: PointerEvent) => { const rect = canvas.getBoundingClientRect(); return { x: (event.clientX - rect.left) * (canvas.width / rect.width), y: (event.clientY - rect.top) * (canvas.height / rect.height) } }; const down = (event: PointerEvent) => { drawing = true; canvas.setPointerCapture(event.pointerId); const p = point(event); context.beginPath(); context.moveTo(p.x, p.y) }; const move = (event: PointerEvent) => { if (!drawing) return; const p = point(event); context.lineTo(p.x, p.y); context.stroke() }; const up = () => { drawing = false }; canvas.addEventListener('pointerdown', down); canvas.addEventListener('pointermove', move); canvas.addEventListener('pointerup', up); canvas.addEventListener('pointerleave', up); return () => { canvas.removeEventListener('pointerdown', down); canvas.removeEventListener('pointermove', move); canvas.removeEventListener('pointerup', up); canvas.removeEventListener('pointerleave', up) } }, [])
  const clearSignature = () => { const canvas = canvasRef.current; const context = canvas?.getContext('2d'); if (canvas && context) context.clearRect(0, 0, canvas.width, canvas.height) }
  const notify = (message: string) => toast.success(message)
  return <div className="flex flex-col gap-6"><Breadcrumb><BreadcrumbList><BreadcrumbItem><BreadcrumbLink>Entregas</BreadcrumbLink></BreadcrumbItem><BreadcrumbSeparator /><BreadcrumbItem><BreadcrumbLink>Registros de entrega</BreadcrumbLink></BreadcrumbItem><BreadcrumbSeparator /><BreadcrumbItem><BreadcrumbPage>Registro #0001</BreadcrumbPage></BreadcrumbItem></BreadcrumbList></Breadcrumb><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h1 className="text-2xl font-bold tracking-tight">Generar registro de entrega</h1><p className="mt-1 text-sm text-muted-foreground">Revisa, firma y comparte el acta de dotación.</p></div><Badge variant="outline" className="w-fit gap-2"><span className="size-2 rounded-full bg-amber-500" /> Pendiente de firma</Badge></div><div className="grid items-start gap-6 xl:grid-cols-[minmax(0,1fr)_340px]"><Card className="bg-muted/50 p-3 shadow-none sm:p-6"><div className="mx-auto max-w-[794px] bg-white p-6 text-slate-900 shadow-md sm:p-10" style={{ minHeight: '980px' }}><div className="flex items-start justify-between border-b-2 border-slate-900 pb-5"><div className="flex items-center gap-3"><div className="flex size-11 items-center justify-center rounded-md bg-teal-700 text-white"><ShieldCheck className="size-6" /></div><div><p className="text-lg font-bold">DotaControl</p><p className="text-[10px] uppercase tracking-[0.16em] text-slate-500">Gestión de dotación empresarial</p></div></div><div className="text-right text-[11px]"><p className="font-bold">ACTA DE ENTREGA DE DOTACIÓN</p><p className="mt-2 text-slate-500">Registro #0001</p><p className="text-slate-500">20 de septiembre de 2026</p></div></div><div className="grid gap-4 border-b border-slate-200 py-6 text-xs sm:grid-cols-2"><div><p className="text-[10px] font-bold uppercase tracking-wide text-slate-400">Nombre completo</p><p className="mt-1 font-semibold">Carlos Rodríguez</p></div><div><p className="text-[10px] font-bold uppercase tracking-wide text-slate-400">Número de identificación</p><p className="mt-1 font-semibold">CC 1.023.456.789</p></div><div><p className="text-[10px] font-bold uppercase tracking-wide text-slate-400">Cargo</p><p className="mt-1 font-semibold">Operario de bodega</p></div><div><p className="text-[10px] font-bold uppercase tracking-wide text-slate-400">Área</p><p className="mt-1 font-semibold">Logística</p></div></div><div className="py-6"><p className="mb-3 text-xs font-bold uppercase tracking-wide">Elementos entregados</p><Table><TableHeader><TableRow className="border-slate-300 hover:bg-transparent"><TableHead className="h-9 text-[10px] text-slate-600">Elemento</TableHead><TableHead className="h-9 text-[10px] text-slate-600">Talla</TableHead><TableHead className="h-9 text-[10px] text-slate-600">Cantidad</TableHead><TableHead className="h-9 text-[10px] text-slate-600">Estado</TableHead></TableRow></TableHeader><TableBody>{[['Camisa manga larga azul','M','2','Buen estado'],['Botas de seguridad punta acero','40','1','Buen estado'],['Guantes anticorte nivel 5','Única','1','Buen estado']].map(([item,size,quantity,condition]) => <TableRow key={item} className="border-slate-200"><TableCell className="py-3 text-[11px] font-medium">{item}</TableCell><TableCell className="py-3 text-[11px]">{size}</TableCell><TableCell className="py-3 text-[11px]">{quantity}</TableCell><TableCell className="py-3 text-[11px]">{condition}</TableCell></TableRow>)}</TableBody></Table></div><p className="border-y border-slate-200 py-5 text-justify text-[11px] leading-5">Por medio de la presente, declaro que he recibido los elementos de dotación relacionados en este documento, en buen estado y a satisfacción. Me comprometo a utilizarlos adecuadamente, conservarlos y velar por su cuidado durante el desarrollo de mis funciones. En caso de deterioro o pérdida por uso indebido, atenderé las disposiciones internas de la organización.</p><div className="mt-auto grid gap-12 pt-28 text-center text-[11px] sm:grid-cols-2"><div><div className="mb-3 border-t border-slate-800" /><p className="font-semibold">Carlos Rodríguez</p><p className="text-slate-500">CC 1.023.456.789</p><p className="mt-1 text-slate-500">Firma del empleado</p></div><div><div className="mb-3 border-t border-slate-800" /><p className="font-semibold">Ana Martínez</p><p className="text-slate-500">CC 1.015.222.840</p><p className="mt-1 text-slate-500">Funcionario que entrega</p></div></div></div></Card><Card className="sticky top-6"><CardHeader><CardTitle className="text-base">Acciones del registro</CardTitle><CardDescription>Completa la firma y comparte el documento.</CardDescription></CardHeader><CardContent className="flex flex-col gap-5"><Alert><FileText /><AlertTitle>Pendiente de firma</AlertTitle><AlertDescription>El empleado aún no ha firmado este registro.</AlertDescription></Alert><div className="flex flex-col gap-2"><div className="flex items-center justify-between"><Label htmlFor="signature">Firma del empleado</Label><Button variant="ghost" size="sm" onClick={clearSignature}>Limpiar</Button></div><canvas id="signature" ref={canvasRef} width="620" height="180" className="touch-none rounded-md border border-dashed bg-background" aria-label="Área para capturar la firma" /><p className="text-xs text-muted-foreground">Dibuja la firma dentro del recuadro.</p></div><Separator /><div className="flex flex-col gap-2"><Button onClick={() => notify('El PDF se descargará en breve.')}><Download data-icon="inline-start" /> Descargar PDF</Button><Button variant="outline" onClick={() => { window.print(); notify('Preparando impresión del acta.') }}><Printer data-icon="inline-start" /> Imprimir</Button><Dialog open={emailOpen} onOpenChange={setEmailOpen}><DialogTrigger className="inline-flex h-9 items-center justify-center gap-2 rounded-md border border-input bg-background px-4 py-2 text-sm font-medium shadow-xs hover:bg-accent hover:text-accent-foreground"><Mail data-icon="inline-start" /> Enviar por correo</DialogTrigger><DialogContent><DialogHeader><DialogTitle>Enviar acta por correo</DialogTitle></DialogHeader><div className="flex flex-col gap-4"><div className="flex flex-col gap-2"><Label htmlFor="record-email">Correo electrónico</Label><Input id="record-email" type="email" placeholder="empleado@empresa.co" /></div><Button onClick={() => { setEmailOpen(false); notify('Acta enviada correctamente por correo.') }}>Enviar</Button></div></DialogContent></Dialog></div></CardContent></Card></div></div>
}

function Record() { return <div className="flex flex-col gap-6"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-sm text-muted-foreground">Entregas / Acta ENT-2026-0098</p><h1 className="mt-1 text-2xl font-bold tracking-tight">Acta de entrega</h1><p className="mt-1 text-sm text-muted-foreground">Revisa y gestiona el documento de entrega.</p></div><Badge variant="outline" className="w-fit gap-1.5"><span className="size-1.5 rounded-full bg-amber-500" /> Pendiente de firma</Badge></div><div className="grid items-start gap-6 xl:grid-cols-[minmax(0,1fr)_300px]"><Card className="overflow-hidden bg-muted/40 p-3 sm:p-6"><div className="mx-auto max-w-2xl bg-white p-8 text-slate-900 shadow-sm sm:p-12"><div className="flex items-start justify-between border-b-2 border-slate-900 pb-5"><div><div className="flex items-center gap-2"><div className="flex size-8 items-center justify-center rounded bg-slate-900 text-white"><ShieldCheck className="size-5" /></div><span className="text-lg font-bold">DotaControl</span></div><p className="mt-2 text-[10px] uppercase tracking-widest text-slate-500">Gestión de dotación empresarial</p></div><div className="text-right text-xs"><p className="font-bold">ACTA DE ENTREGA</p><p className="mt-1 text-slate-500">No. ENT-2026-0098</p><p className="mt-1 text-slate-500">20 de septiembre de 2026</p></div></div><div className="grid grid-cols-2 gap-4 border-b py-5 text-xs"><div><p className="text-[10px] uppercase text-slate-400">Empleado</p><p className="mt-1 font-semibold">Carlos Rodríguez</p><p className="mt-1 text-slate-500">CC 1.023.456.789</p></div><div><p className="text-[10px] uppercase text-slate-400">Cargo / Área</p><p className="mt-1 font-semibold">Operario de bodega</p><p className="mt-1 text-slate-500">Logística</p></div></div><div className="py-5"><p className="mb-3 text-xs font-bold">Elementos entregados</p><Table><TableHeader><TableRow className="border-slate-200"><TableHead className="h-8 px-2 text-[10px] text-slate-500">Elemento</TableHead><TableHead className="h-8 px-2 text-[10px] text-slate-500">Talla</TableHead><TableHead className="h-8 px-2 text-right text-[10px] text-slate-500">Cantidad</TableHead><TableHead className="h-8 px-2 text-right text-[10px] text-slate-500">Estado</TableHead></TableRow></TableHeader><TableBody><TableRow className="border-slate-200"><TableCell className="px-2 py-2 text-xs">Camisa manga larga azul</TableCell><TableCell className="px-2 py-2 text-xs">M</TableCell><TableCell className="px-2 py-2 text-right text-xs">1</TableCell><TableCell className="px-2 py-2 text-right text-xs">Bueno</TableCell></TableRow><TableRow className="border-slate-200"><TableCell className="px-2 py-2 text-xs">Botas de seguridad punta acero</TableCell><TableCell className="px-2 py-2 text-xs">42</TableCell><TableCell className="px-2 py-2 text-right text-xs">1</TableCell><TableCell className="px-2 py-2 text-right text-xs">Bueno</TableCell></TableRow></TableBody></Table></div><p className="border-t pt-5 text-[10px] leading-5 text-slate-500">Por medio de la presente, declaro haber recibido a satisfacción los elementos relacionados en esta acta, en buen estado de conservación y funcionamiento. Me comprometo a utilizarlos adecuadamente y devolver aquellos que tengan carácter reutilizable al finalizar la relación laboral.</p><div className="mt-16 grid grid-cols-2 gap-10 text-center text-[10px]"><div className="border-t border-slate-800 pt-2">Firma del empleado<br /><span className="text-slate-500">Carlos Rodríguez</span></div><div className="border-t border-slate-800 pt-2">Firma del responsable<br /><span className="text-slate-500">Ana Martínez</span></div></div></div></Card><Card className="h-fit"><CardHeader><CardTitle className="text-base">Acciones del acta</CardTitle><CardDescription>Gestiona la firma y distribución.</CardDescription></CardHeader><CardContent className="flex flex-col gap-3"><div className="rounded-lg border border-dashed p-5 text-center"><div className="mx-auto mb-2 flex size-9 items-center justify-center rounded-full bg-muted"><PenLine className="size-4 text-muted-foreground" /></div><p className="text-xs font-medium">Firma del empleado</p><p className="mt-1 text-[11px] text-muted-foreground">El empleado puede firmar aquí</p><Button variant="outline" size="sm" className="mt-3 w-full">Capturar firma</Button></div><Separator /><Button variant="outline" onClick={() => toast.success('Descarga preparada')}><Download data-icon="inline-start" /> Descargar PDF</Button><Button variant="outline" onClick={() => window.print()}><Printer data-icon="inline-start" /> Imprimir</Button><Dialog><DialogTrigger><Button><Mail data-icon="inline-start" /> Enviar por correo</Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>Enviar acta por correo</DialogTitle></DialogHeader><p className="text-sm text-muted-foreground">Se enviará una copia del acta a carlos.rodriguez@empresa.co</p><Button onClick={() => toast.success('Acta enviada correctamente')}>Confirmar envío</Button></DialogContent></Dialog></CardContent></Card></div></div> }

function Login({ setActive }: { setActive: (id: string) => void }) { const [show, setShow] = useState(false); return <div className="flex min-h-screen bg-muted/30"><div className="flex w-full items-center justify-center p-6 lg:w-1/2"><Card className="w-full max-w-md border-0 shadow-none sm:border sm:shadow-sm"><CardHeader className="gap-5 p-7 sm:p-9"><Logo /><div className="pt-3"><CardTitle className="text-2xl">Bienvenida de nuevo</CardTitle><CardDescription className="mt-2">Ingresa a tu cuenta para continuar.</CardDescription></div></CardHeader><CardContent className="flex flex-col gap-5 px-7 sm:px-9"><div className="flex flex-col gap-2"><Label>Correo electrónico</Label><Input placeholder="ana@empresa.co" type="email" /></div><div className="flex flex-col gap-2"><div className="flex justify-between"><Label>Contraseña</Label><Button variant="link" className="h-auto p-0 text-xs">¿Olvidaste tu contraseña?</Button></div><div className="relative"><Input placeholder="••••••••" type={show ? 'text' : 'password'} className="pr-10" /><button aria-label="Mostrar contraseña" onClick={() => setShow(!show)} className="absolute right-3 top-2.5 text-muted-foreground">{show ? <EyeOff className="size-4" /> : <Eye className="size-4" />}</button></div></div><div className="flex items-center gap-2"><Checkbox id="remember" /><Label htmlFor="remember" className="text-xs font-normal">Recordarme en este dispositivo</Label></div><Button size="lg" onClick={() => setActive('dashboard')}>Iniciar sesión <ArrowRight data-icon="inline-end" /></Button><p className="text-center text-xs text-muted-foreground">¿No tienes una cuenta? <Button variant="link" className="h-auto p-0 text-xs" onClick={() => setActive('register')}>Crear cuenta</Button></p></CardContent></Card></div><div className="relative hidden flex-1 overflow-hidden bg-primary p-12 text-primary-foreground lg:flex lg:flex-col lg:justify-between"><div className="absolute -right-20 -top-20 size-80 rounded-full border border-primary-foreground/10" /><div className="absolute -bottom-32 -left-24 size-96 rounded-full border border-primary-foreground/10" /><Logo /><div className="relative max-w-md"><p className="mb-4 text-sm font-medium text-primary-foreground/70">CONTROL TOTAL DE TU DOTACIÓN</p><h2 className="text-4xl font-bold leading-tight tracking-tight">Todo lo que necesitas para entregar con confianza.</h2><p className="mt-5 text-sm leading-6 text-primary-foreground/70">Centraliza inventario, empleados y actas de entrega en un solo lugar.</p></div><p className="text-xs text-primary-foreground/50">© 2026 DotaControl · Hecho para equipos que avanzan</p></div></div> }

function Register({ setActive }: { setActive: (id: string) => void }) { return <div className="flex min-h-screen items-center justify-center bg-muted/30 p-6"><Card className="w-full max-w-3xl"><CardHeader><Logo /><div className="pt-4"><CardTitle className="text-2xl">Crea tu cuenta</CardTitle><CardDescription>Configura tu perfil de administradora en DotaControl.</CardDescription></div></CardHeader><CardContent className="grid gap-5 sm:grid-cols-2"><Field label="Nombre completo" placeholder="Ana Martínez" /><Field label="Número de identificación" placeholder="1.023.456.789" /><Field label="Correo electrónico" placeholder="ana@empresa.co" type="email" /><Field label="Teléfono" placeholder="300 123 4567" /><div className="flex flex-col gap-2"><Label className="text-xs font-medium">Cargo</Label><Select><SelectTrigger><SelectValue placeholder="Selecciona un cargo" /></SelectTrigger><SelectContent><SelectItem value="admin">Administradora</SelectItem><SelectItem value="hr">Gestión humana</SelectItem><SelectItem value="warehouse">Operario de bodega</SelectItem></SelectContent></Select></div><div className="flex flex-col gap-2"><Label className="text-xs font-medium">Área</Label><Select><SelectTrigger><SelectValue placeholder="Selecciona un área" /></SelectTrigger><SelectContent><SelectItem value="log">Logística</SelectItem><SelectItem value="ops">Operaciones</SelectItem><SelectItem value="maint">Mantenimiento</SelectItem></SelectContent></Select></div><Field label="Contraseña" placeholder="Mínimo 8 caracteres" type="password" /><Field label="Confirmar contraseña" placeholder="Repite tu contraseña" type="password" /><div className="sm:col-span-2"><div className="mb-2 flex justify-between text-[11px] text-muted-foreground"><span>Seguridad de contraseña</span><span className="font-medium text-primary">Fuerte</span></div><div className="flex gap-1"><div className="h-1.5 flex-1 rounded-full bg-primary" /><div className="h-1.5 flex-1 rounded-full bg-primary" /><div className="h-1.5 flex-1 rounded-full bg-primary" /><div className="h-1.5 flex-1 rounded-full bg-muted" /></div></div><div className="flex items-center gap-2 sm:col-span-2"><Checkbox id="terms" /><Label htmlFor="terms" className="text-xs font-normal">Acepto los términos y condiciones de uso.</Label></div></CardContent><CardFooter className="flex-col gap-4 sm:flex-row sm:justify-between"><Button variant="ghost" onClick={() => setActive('login')}>Volver al inicio de sesión</Button><Button onClick={() => setActive('dashboard')}>Crear cuenta <ArrowRight data-icon="inline-end" /></Button></CardFooter></Card></div> }

export default function DotaControl() { const [active, setActive] = useState('dashboard'); const [mobileOpen, setMobileOpen] = useState(false); const [collapsed, setCollapsed] = useState(false); if (active === 'login') return <Login setActive={setActive} />; if (active === 'register') return <Register setActive={setActive} />; if (active === 'new-item') return <AppShell active={active} setActive={setActive} mobileOpen={mobileOpen} setMobileOpen={setMobileOpen} collapsed={collapsed} setCollapsed={setCollapsed}><RegisterItem setActive={setActive} /></AppShell>; const titles: Record<string, [string, string, string]> = { dashboard: ['Dashboard', 'Resumen general de la operación', ''], inventory: ['Elementos de dotación', 'Administra el catálogo y existencias de tu organización.', 'Registrar elemento'], categories: ['Categorías', 'Organiza los elementos por familias de dotación.', 'Nueva categoría'], movements: ['Movimientos de stock', 'Consulta las entradas, salidas y ajustes del inventario.', 'Registrar movimiento'], employees: ['Empleados', 'Consulta y administra el personal de la organización.', 'Nuevo empleado'], delivery: ['Registrar entrega', 'Asigna elementos de dotación a un empleado.', ''], record: ['Acta de entrega', 'Revisa y gestiona el documento de entrega.', ''], reports: ['Reportes', 'Analiza el comportamiento de inventario y entregas.', ''], settings: ['Configuración', 'Gestiona las preferencias de DotaControl.', ''] }; const [title, description, action] = titles[active] || titles.dashboard; return <div className="flex min-h-screen bg-muted/30"><div className={collapsed ? 'hidden' : 'lg:block'}><AppSidebar active={active} setActive={setActive} /></div><Sheet open={mobileOpen} onOpenChange={setMobileOpen}><SheetContent side="left" className="w-72 p-0"><AppSidebar active={active} setActive={setActive} mobile onClose={() => setMobileOpen(false)} /></SheetContent></Sheet><div className="flex min-w-0 flex-1 flex-col"><Topbar setActive={setActive} onMenu={() => setMobileOpen(true)} collapsed={collapsed} setCollapsed={() => setCollapsed(!collapsed)} /><main className="flex-1 overflow-auto p-4 sm:p-8"><div className="mx-auto max-w-7xl"><div className="mb-6 flex flex-col gap-4 border-b pb-6 sm:flex-row sm:items-end sm:justify-between"><div><Breadcrumb className="mb-3"><BreadcrumbList><BreadcrumbItem><BreadcrumbLink href="#">Inicio</BreadcrumbLink></BreadcrumbItem><BreadcrumbSeparator /><BreadcrumbItem><BreadcrumbPage>{title}</BreadcrumbPage></BreadcrumbItem></BreadcrumbList></Breadcrumb><h1 className="text-2xl font-bold tracking-tight">{title}</h1><p className="mt-1 text-sm text-muted-foreground">{description}</p></div>{action && <Button onClick={() => toast.success('Acción disponible próximamente')}><Plus data-icon="inline-start" /> {action}</Button>}</div>{active === 'dashboard' && <Dashboard setActive={setActive} />}{active === 'inventory' && <Inventory setActive={setActive} />}{active === 'delivery' && <Delivery setActive={setActive} />}{active === 'record' && <DeliveryRecordDetail />}{active === 'employees' && <Dashboard setActive={setActive} />}{['categories', 'movements', 'reports', 'settings'].includes(active) && <Card><CardContent className="p-8 text-center text-sm text-muted-foreground">Esta sección está lista para ser configurada.</CardContent></Card>}</div></main></div></div> }

function AppShell({ active, setActive, mobileOpen, setMobileOpen, collapsed, setCollapsed, children }: { active: string, setActive: (id: string) => void, mobileOpen: boolean, setMobileOpen: (open: boolean) => void, collapsed: boolean, setCollapsed: (value: boolean) => void, children: React.ReactNode }) { return <div className="flex min-h-screen bg-muted/30"><div className={collapsed ? 'hidden' : 'lg:block'}><AppSidebar active={active} setActive={setActive} /></div><Sheet open={mobileOpen} onOpenChange={setMobileOpen}><SheetContent side="left" className="w-72 p-0"><AppSidebar active={active} setActive={setActive} mobile onClose={() => setMobileOpen(false)} /></SheetContent></Sheet><div className="flex min-w-0 flex-1 flex-col"><Topbar setActive={setActive} onMenu={() => setMobileOpen(true)} collapsed={collapsed} setCollapsed={() => setCollapsed(!collapsed)} /><main className="flex-1 overflow-auto p-4 sm:p-8"><div className="mx-auto max-w-7xl"><Breadcrumb className="mb-4"><BreadcrumbList><BreadcrumbItem><BreadcrumbLink>Inventario</BreadcrumbLink></BreadcrumbItem><BreadcrumbSeparator /><BreadcrumbItem><BreadcrumbLink>Elementos</BreadcrumbLink></BreadcrumbItem><BreadcrumbSeparator /><BreadcrumbItem><BreadcrumbPage>Nuevo elemento</BreadcrumbPage></BreadcrumbItem></BreadcrumbList></Breadcrumb><div className="mb-6 flex flex-col justify-between gap-4 border-b pb-6 sm:flex-row sm:items-end"><div><h1 className="text-2xl font-bold tracking-tight">Registrar elemento</h1><p className="mt-1 text-sm text-muted-foreground">Agrega un nuevo elemento al catálogo de dotación.</p></div></div>{children}</div></main></div></div> }

const itemSchema = z.object({
  name: z.string().min(2, 'Ingresa el nombre del elemento.'),
  sku: z.string().min(2, 'Ingresa un código válido.'),
  category: z.string().min(1, 'Selecciona una categoría.'),
  description: z.string().min(5, 'Agrega una descripción breve.'),
  size: z.string().min(1, 'Selecciona una talla.'),
  color: z.string().min(2, 'Ingresa el color.'),
  brand: z.string().min(2, 'Ingresa la marca.'),
  material: z.string().min(2, 'Ingresa el material.'),
  unit: z.string().min(1, 'Selecciona la unidad.'),
  initialStock: z.coerce.number().int().min(0, 'Usa un número mayor o igual a 0.'),
  minimumStock: z.coerce.number().int().min(0, 'Usa un número mayor o igual a 0.'),
  unitCost: z.coerce.number().min(0, 'Usa un costo válido.'),
  supplier: z.string().min(2, 'Selecciona un proveedor.'),
  entryDate: z.string().min(1, 'Selecciona la fecha de entrada.'),
  location: z.string().min(2, 'Ingresa la ubicación.'),
  requiresSize: z.boolean(),
  expiration: z.boolean(),
  returnable: z.boolean(),
})
type ItemFormValues = z.infer<typeof itemSchema>

const recentItems = [
  ['UNI-001', 'Overol industrial', 'Uniforme', '48', 'En stock'],
  ['CAL-014', 'Botas de seguridad', 'Calzado', '6', 'Stock bajo'],
  ['PPE-006', 'Casco de protección', 'EPP', '0', 'Agotado'],
  ['PPE-021', 'Guantes de nitrilo', 'EPP', '32', 'En stock'],
  ['HER-008', 'Arnés de seguridad', 'Herramientas', '9', 'En stock'],
  ['ACC-017', 'Gafas de protección', 'Accesorios', '4', 'Stock bajo'],
  ['UNI-032', 'Chaleco reflectivo', 'Uniforme', '25', 'En stock'],
]

function ItemField({ control, name, label, placeholder, type = 'text' }: { control: any, name: keyof ItemFormValues, label: string, placeholder?: string, type?: string }) {
  return <FormField control={control} name={name} render={({ field }) => <FormItem><FormLabel className="text-xs font-medium">{label}</FormLabel><FormControl><Input {...field} value={field.value as string | number} type={type} placeholder={placeholder} /></FormControl><FormMessage /></FormItem>} />
}

function ItemSelect({ control, name, label, placeholder, options }: { control: any, name: keyof ItemFormValues, label: string, placeholder: string, options: [string, string][] }) {
  return <FormField control={control} name={name} render={({ field }) => <FormItem><FormLabel className="text-xs font-medium">{label}</FormLabel><Select onValueChange={field.onChange} defaultValue={(field.value as string | null) ?? ''}><FormControl><SelectTrigger><SelectValue placeholder={placeholder} /></SelectTrigger></FormControl><SelectContent>{options.map(([value, text]) => <SelectItem key={value} value={value}>{text}</SelectItem>)}</SelectContent></Select><FormMessage /></FormItem>} />
}

function RegisterItem({ setActive }: { setActive: (id: string) => void }) {
  const form = useForm<z.input<typeof itemSchema>, any, ItemFormValues>({ resolver: zodResolver(itemSchema), defaultValues: { name: '', sku: '', category: '', description: '', size: '', color: '', brand: '', material: '', unit: '', initialStock: 0, minimumStock: 5, unitCost: 0, supplier: '', entryDate: '20/09/2026', location: '', requiresSize: true, expiration: false, returnable: false } })
  const [image, setImage] = useState<string | null>(null)
  const [supplierOpen, setSupplierOpen] = useState(false)
  const [dateOpen, setDateOpen] = useState(false)
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(new Date(2026, 8, 20))
  const onSubmit = (values: ItemFormValues) => { toast.success(`Elemento ${values.name} guardado correctamente.`); setActive('inventory') }
  return <Form {...form}><form onSubmit={form.handleSubmit(onSubmit)} className="flex flex-col gap-6 pb-24">
    <div className="grid gap-5 xl:grid-cols-2">
      <Card><CardHeader><CardTitle className="text-base">Información general</CardTitle><CardDescription>Identifica el elemento dentro del catálogo.</CardDescription></CardHeader><CardContent className="grid gap-4"><ItemField control={form.control} name="name" label="Nombre del elemento" placeholder="Ej. Overol industrial" /><ItemField control={form.control} name="sku" label="SKU / Código" placeholder="Ej. UNI-001" /><ItemSelect control={form.control} name="category" label="Categoría" placeholder="Selecciona una categoría" options={ [['uniform','Uniforme'],['footwear','Calzado'],['ppe','EPP'],['tools','Herramientas'],['accessories','Accesorios']] } /><FormField control={form.control} name="description" render={({ field }) => <FormItem><FormLabel className="text-xs font-medium">Descripción</FormLabel><FormControl><Textarea {...field} placeholder="Describe el elemento y sus usos..." /></FormControl><FormMessage /></FormItem>} /></CardContent></Card>
      <Card><CardHeader><CardTitle className="text-base">Especificaciones</CardTitle><CardDescription>Detalla las características del elemento.</CardDescription></CardHeader><CardContent className="grid gap-4 sm:grid-cols-2"><ItemSelect control={form.control} name="size" label="Talla" placeholder="Selecciona" options={ [['unique','Única'],['s','S'],['m','M'],['l','L'],['xl','XL']] } /><ItemField control={form.control} name="color" label="Color" placeholder="Ej. Azul marino" /><ItemField control={form.control} name="brand" label="Marca" placeholder="Ej. 3M" /><ItemField control={form.control} name="material" label="Material" placeholder="Ej. Poliéster" /><ItemSelect control={form.control} name="unit" label="Unidad de medida" placeholder="Selecciona" options={ [['unit','Unidad'],['pair','Par'],['box','Caja'],['kit','Kit']] } /></CardContent></Card>
      <Card><CardHeader><CardTitle className="text-base">Inventario</CardTitle><CardDescription>Configura existencias, costos y almacenamiento.</CardDescription></CardHeader><CardContent className="grid gap-4 sm:grid-cols-2"><ItemField control={form.control} name="initialStock" label="Stock inicial" type="number" /><ItemField control={form.control} name="minimumStock" label="Alerta de stock mínimo" type="number" /><ItemField control={form.control} name="unitCost" label="Costo unitario" placeholder="$ 0" type="number" /><FormField control={form.control} name="supplier" render={({ field }) => <FormItem><FormLabel className="text-xs font-medium">Proveedor</FormLabel><Popover open={supplierOpen} onOpenChange={setSupplierOpen}><PopoverTrigger><Button type="button" variant="outline" className="w-full justify-between font-normal">{field.value || 'Buscar proveedor'}<ChevronDown /></Button></PopoverTrigger><PopoverContent className="w-[--radix-popover-trigger-width] p-0"><Command><CommandInput placeholder="Buscar proveedor..." /><CommandList><CommandEmpty>Sin resultados.</CommandEmpty><CommandGroup>{['Segurindustrias SAS','EPP Colombia','Suministros Andinos'].map((supplier) => <CommandItem key={supplier} value={supplier} onSelect={() => { field.onChange(supplier); setSupplierOpen(false) }}>{supplier}</CommandItem>)}</CommandGroup></CommandList></Command></PopoverContent></Popover><FormMessage /></FormItem>} /><FormField control={form.control} name="entryDate" render={({ field }) => <FormItem><FormLabel className="text-xs font-medium">Fecha de entrada</FormLabel><Popover open={dateOpen} onOpenChange={setDateOpen}><PopoverTrigger><Button type="button" variant="outline" className="w-full justify-start font-normal"><CalendarDays />{field.value || 'Selecciona una fecha'}</Button></PopoverTrigger><PopoverContent className="w-auto p-0"><Calendar mode="single" selected={selectedDate} onSelect={(date) => { setSelectedDate(date); field.onChange(date ? date.toLocaleDateString('es-CO') : ''); setDateOpen(false) }} /></PopoverContent></Popover><FormMessage /></FormItem>} /><ItemField control={form.control} name="location" label="Ubicación de almacenamiento" placeholder="Ej. Bodega A · Estante 03" /></CardContent></Card>
      <Card><CardHeader><CardTitle className="text-base">Imagen del elemento</CardTitle><CardDescription>Agrega una imagen para identificarlo rápidamente.</CardDescription></CardHeader><CardContent><label className="flex min-h-36 cursor-pointer flex-col items-center justify-center gap-2 rounded-lg border border-dashed bg-muted/30 p-6 text-center hover:bg-muted/50">{image ? <><img src={image} alt="Vista previa del elemento" className="max-h-28 rounded-md object-contain" /><Button type="button" variant="ghost" size="sm" onClick={(event) => { event.preventDefault(); setImage(null) }}>Quitar imagen</Button></> : <><Upload className="text-muted-foreground" /><p className="text-sm font-medium">Arrastra una imagen o haz clic para cargar</p><p className="text-xs text-muted-foreground">PNG, JPG hasta 5 MB</p></>}<input className="sr-only" type="file" accept="image/*" onChange={(event) => { const file = event.target.files?.[0]; if (file) setImage(URL.createObjectURL(file)) }} /></label></CardContent></Card>
    </div>
    <Card><CardHeader><CardTitle className="text-base">Opciones</CardTitle><CardDescription>Define reglas especiales para este elemento.</CardDescription></CardHeader><CardContent className="grid gap-4 sm:grid-cols-3"><SwitchField control={form.control} name="requiresSize" label="Requiere talla" /><SwitchField control={form.control} name="expiration" label="Tiene fecha de vencimiento" /><SwitchField control={form.control} name="returnable" label="Reutilizable / retornable" /></CardContent></Card>
    <Card><CardHeader><CardTitle className="text-base">Elementos registrados recientemente</CardTitle><CardDescription>Últimos elementos agregados al catálogo.</CardDescription></CardHeader><CardContent><Table><TableHeader><TableRow><TableHead>Código</TableHead><TableHead>Nombre</TableHead><TableHead>Categoría</TableHead><TableHead>Stock</TableHead><TableHead>Estado</TableHead><TableHead className="text-right">Acciones</TableHead></TableRow></TableHeader><TableBody>{recentItems.map(([code, name, category, stock, status]) => <TableRow key={code}><TableCell className="font-mono text-xs">{code}</TableCell><TableCell className="font-medium">{name}</TableCell><TableCell>{category}</TableCell><TableCell>{stock}</TableCell><TableCell><Badge variant={status === 'En stock' ? 'secondary' : status === 'Stock bajo' ? 'outline' : 'destructive'}>{status}</Badge></TableCell><TableCell className="text-right"><DropdownMenu><DropdownMenuTrigger><Button variant="ghost" size="icon" aria-label={`Acciones para ${name}`}><MoreHorizontal /></Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem>Ver</DropdownMenuItem><DropdownMenuItem>Editar</DropdownMenuItem><DropdownMenuItem className="text-destructive">Eliminar</DropdownMenuItem></DropdownMenuContent></DropdownMenu></TableCell></TableRow>)}</TableBody></Table></CardContent></Card>
    <div className="fixed inset-x-0 bottom-0 z-10 flex justify-end gap-3 border-t bg-background/95 px-4 py-3 backdrop-blur sm:px-8"><Button type="button" variant="outline" onClick={() => setActive('inventory')}>Cancelar</Button><Button type="submit"><Check data-icon="inline-start" />Guardar elemento</Button></div>
  </form></Form>
}

function SwitchField({ control, name, label }: { control: any, name: keyof ItemFormValues, label: string }) { return <FormField control={control} name={name} render={({ field }) => <FormItem className="flex items-center justify-between gap-4 rounded-lg border p-3"><FormLabel className="text-sm font-normal">{label}</FormLabel><FormControl><Switch checked={field.value as boolean} onCheckedChange={field.onChange} /></FormControl></FormItem>} /> }

function PenLine(props: React.ComponentProps<typeof FileText>) { return <FileText {...props} /> }
